<?php
declare(strict_types=1);ob_start();session_start();require dirname(__DIR__,2).'/config/config.php';
function teacher_dashboard_json(int $status,array $data):never{http_response_code($status);header('Content-Type: application/json; charset=utf-8');header('Cache-Control: no-store');if(ob_get_level())ob_clean();echo json_encode($data,JSON_THROW_ON_ERROR|JSON_UNESCAPED_UNICODE);exit;}
if(!signed_in())teacher_dashboard_json(401,['ok'=>false,'message'=>'Your session expired. Sign in again.']);require_sign_in();if(!empty($_SESSION['must_change_password']))teacher_dashboard_json(403,['ok'=>false,'message'=>'Change your password before continuing.']);if(($_SESSION['role']??'')!=='teacher')teacher_dashboard_json(403,['ok'=>false,'message'=>'This dashboard is for teacher accounts.']);$uid=(int)$_SESSION['user_id'];$school=filter_var($_GET['school_id']??null,FILTER_VALIDATE_INT);if(!$school)teacher_dashboard_json(422,['ok'=>false,'message'=>'Choose a school.']);
try{$db=db();$q=$db->prepare('SELECT 1 FROM school_memberships WHERE user_id=? AND school_id=?');$q->execute([$uid,$school]);if(!$q->fetchColumn())teacher_dashboard_json(403,['ok'=>false,'message'=>'That school is outside your access.']);
$q=$db->prepare('SELECT DISTINCT a.class_level,c.id class_id,a.subject,cs.id subject_id FROM teacher_assignments a JOIN school_classes c ON c.school_id=a.school_id AND c.name=a.class_level JOIN school_class_subjects cs ON cs.class_id=c.id AND cs.name=a.subject WHERE a.user_id=? AND a.school_id=? AND a.active=1 ORDER BY a.class_level,a.subject');$q->execute([$uid,$school]);$assignments=$q->fetchAll();
$q=$db->prepare("SELECT lp.id,lp.title,lp.scheduled_for,lp.status,c.name class_name,cs.name subject_name,st.topic FROM lesson_plans lp JOIN schemes_of_work sw ON sw.id=lp.scheme_id AND sw.school_id=lp.school_id JOIN scheme_topics st ON st.id=lp.topic_id AND st.scheme_id=sw.id JOIN school_classes c ON c.id=sw.class_id AND c.school_id=sw.school_id JOIN school_class_subjects cs ON cs.id=sw.subject_id AND cs.class_id=c.id WHERE lp.school_id=? AND lp.teacher_id=? AND lp.status IN ('approved','completed') AND lp.scheduled_for BETWEEN CURRENT_DATE AND DATE_ADD(CURRENT_DATE,INTERVAL 14 DAY) ORDER BY lp.scheduled_for,lp.id LIMIT 12");$q->execute([$school,$uid]);$lessons=$q->fetchAll();
$q=$db->prepare("SELECT COUNT(*) FROM lesson_plans WHERE school_id=? AND teacher_id=? AND status='approved' AND scheduled_for<CURRENT_DATE");$q->execute([$school,$uid]);$pastUnconfirmed=(int)$q->fetchColumn();
$q=$db->prepare("SELECT status,COUNT(*) total FROM teacher_reports WHERE school_id=? AND teacher_id=? AND status IN ('draft','submitted','approved','returned') GROUP BY status");$q->execute([$school,$uid]);$reportCounts=['draft'=>0,'submitted'=>0,'approved'=>0,'returned'=>0];foreach($q->fetchAll() as $r)$reportCounts[$r['status']]=(int)$r['total'];
$q=$db->prepare("SELECT COUNT(DISTINCT x.id) FROM school_exams x JOIN school_classes c ON c.id=x.class_id AND c.school_id=x.school_id JOIN school_class_subjects cs ON cs.id=x.subject_id AND cs.class_id=c.id JOIN teacher_assignments a ON a.school_id=x.school_id AND a.class_level=c.name AND a.subject=cs.name AND a.user_id=? AND a.active=1 WHERE x.school_id=? AND x.status='results_open'");$q->execute([$uid,$school]);$openExams=(int)$q->fetchColumn();$q=$db->prepare("SELECT x.id,x.name,x.academic_year,x.term,x.exam_date,x.status,c.name class_name,cs.name subject_name FROM school_exams x JOIN school_classes c ON c.id=x.class_id AND c.school_id=x.school_id JOIN school_class_subjects cs ON cs.id=x.subject_id AND cs.class_id=c.id JOIN teacher_assignments a ON a.school_id=x.school_id AND a.class_level=c.name AND a.subject=cs.name AND a.user_id=? AND a.active=1 WHERE x.school_id=? AND x.status IN ('scheduled','results_open') AND (x.status='results_open' OR x.exam_date>=CURRENT_DATE) ORDER BY (x.status='results_open') DESC,x.exam_date,x.id LIMIT 12");$q->execute([$uid,$school]);$exams=$q->fetchAll();
teacher_dashboard_json(200,['ok'=>true,'data'=>['assignments'=>$assignments,'lessons'=>$lessons,'past_unconfirmed_lessons'=>$pastUnconfirmed,'reports'=>$reportCounts,'exams'=>$exams,'open_exams'=>$openExams,'today'=>date('Y-m-d')]]);
}catch(Throwable $e){error_log('Teacher dashboard request failed: '.$e->getMessage());teacher_dashboard_json(500,['ok'=>false,'message'=>'Teacher dashboard data could not be loaded.']);}
